mapper.update:
UPDATE stock SET quantity = quantity - #{quantity}
WHERE product_id = #{productId}
  AND warehouse_id = #{warehouseId}
  AND quantity >= #{quantity}

mapper.select:
SELECT s.id, p.name AS product_name, p.code AS product_code, w.name AS warehouse_name, s.quantity, p.warning_qty, CASE WHEN s.quantity <= p.warning_qty THEN 1 ELSE 0 END AS warn_flag FROM stock s LEFT JOIN product p ON s.product_id = p.id LEFT JOIN warehouse w ON s.warehouse_id = w.id
AND (p.name LIKE CONCAT('%', #{dto.keyword}, '%') OR p.code LIKE CONCAT('%', #{dto.keyword}, '%'))
AND s.warehouse_id = #{dto.warehouseId}
ORDER BY s.update_time DESC LIMIT #{offset}, #{dto.pageSize}

SELECT COUNT(*) FROM stock s LEFT JOIN product p ON s.product_id = p.id
AND (p.name LIKE CONCAT('%', #{dto.keyword}, '%') OR p.code LIKE CONCAT('%', #{dto.keyword}, '%'))
AND s.warehouse_id = #{dto.warehouseId}
